def write_result(self, buf):
    indent = 0
    id_section = ''
    frame = self.frame
    _classes = ['dataframe']
    use_mathjax = get_option('display.html.use_mathjax')
    if not use_mathjax:
        _classes.append('tex2jax_ignore')
    if self.classes is not None:
        if isinstance(self.classes, str):
            self.classes = self.classes.split()
        if not isinstance(self.classes, (list, tuple)):
            raise AssertionError('classes must be list or tuple, not {typ}'
                .format(typ=type(self.classes)))
        _classes.extend(self.classes)
    if self.notebook:
        self.write('<div>')
    self.write_style()
    if self.table_id is not None:
        id_section = ' id="{table_id}"'.format(table_id=self.table_id)
    self.write('<table border="{border}" class="{cls}"{id_section}>'.format
        (border=self.border, cls=' '.join(_classes), id_section=id_section),
        indent)
    indent += self.indent_delta
    indent = self._write_header(indent)
    indent = self._write_body(indent)
    self.write('</table>', indent)
    if self.should_show_dimensions:
        by = chr(215) if compat.PY3 else unichr(215)
        self.write(u('<p>{rows} rows {by} {cols} columns</p>').format(rows=
            len(frame), by=by, cols=len(frame.columns)))
    if self.notebook:
        self.write('</div>')
    buffer_put_lines(buf, self.elements)

